            : walk_row(slab, spec.probe, gate);
        total = sweep_e(total, part);
    }
    return {
        spec.case_id,
        total,
        static_cast<std::int64_t>(slabs.size()),
        spec.probe.lane,
        spec.probe.skipping,
    };
}

}  // namespace loam
